//! Error codes and the error type shared by every layer.

use std::fmt;

/// The failure codes of the protocol. No other code is ever returned.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ErrorCode {
    /// The line is not a JSON object with a string `Command` naming a known command.
    InvalidRequest,
    /// A required parameter is absent.
    MissingParameter,
    /// A parameter or attribute has the wrong type or a disallowed value.
    InvalidParameterValue,
    /// `CreateQueue` was given a name that breaks the naming rules.
    QueueNameInvalid,
    /// `CreateQueue` named an existing queue with different attributes.
    QueueAlreadyExists,
    /// The named queue, or the named dead-letter queue, does not exist.
    QueueDoesNotExist,
    /// The receipt handle was never issued.
    ReceiptHandleInvalid,
    /// The receipt handle was issued but is not usable (any more).
    ReceiptHandleExpired,
    /// The request asks for something this type of queue does not support.
    UnsupportedOperation,
    /// A queue-count or message-count limit is reached.
    LimitExceeded,
}

impl ErrorCode {
    /// The code as it appears on the wire.
    pub fn as_str(self) -> &'static str {
        match self {
            Self::InvalidRequest => "InvalidRequest",
            Self::MissingParameter => "MissingParameter",
            Self::InvalidParameterValue => "InvalidParameterValue",
            Self::QueueNameInvalid => "QueueNameInvalid",
            Self::QueueAlreadyExists => "QueueAlreadyExists",
            Self::QueueDoesNotExist => "QueueDoesNotExist",
            Self::ReceiptHandleInvalid => "ReceiptHandleInvalid",
            Self::ReceiptHandleExpired => "ReceiptHandleExpired",
            Self::UnsupportedOperation => "UnsupportedOperation",
            Self::LimitExceeded => "LimitExceeded",
        }
    }
}

/// A failed command: a code plus a human-readable message.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Error {
    code: ErrorCode,
    message: String,
}

impl Error {
    /// Creates an error with the given code and message.
    pub fn new(code: ErrorCode, message: impl Into<String>) -> Self {
        Self {
            code,
            message: message.into(),
        }
    }

    /// The machine-readable code.
    pub fn code(&self) -> ErrorCode {
        self.code
    }

    /// The human-readable message.
    pub fn message(&self) -> &str {
        &self.message
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}: {}", self.code.as_str(), self.message)
    }
}

impl std::error::Error for Error {}

/// Result type used throughout the crate.
pub type Result<T> = std::result::Result<T, Error>;
