//! Parsing of command lines into typed requests.
//!
//! Validation follows the order of the specification: request shape, required parameters,
//! then parameter values. Rules that need broker state are applied later by the broker.

use std::ops::RangeInclusive;

use serde_json::{Map, Value};

use crate::error::{Error, ErrorCode, Result};

/// Largest number of seconds one `Tick` may advance the clock by.
const TICK_SECONDS: RangeInclusive<u32> = 0..=1_209_600;

/// A fully shape- and type-checked command.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Request {
    /// Advances the virtual clock.
    Tick {
        /// Seconds to add to the clock.
        seconds: u32,
    },
}

/// Parses one input line.
pub fn parse(line: &[u8]) -> Result<Request> {
    let text = std::str::from_utf8(line).map_err(|_| invalid_request("line is not valid UTF-8"))?;
    let value: Value =
        serde_json::from_str(text).map_err(|err| invalid_request(format!("not valid JSON: {err}")))?;
    let Value::Object(members) = value else {
        return Err(invalid_request("line is not a JSON object"));
    };
    let Some(Value::String(command)) = members.get("Command") else {
        return Err(invalid_request("`Command` is missing or not a string"));
    };
    let params = Params(&members);
    match command.as_str() {
        "Tick" => {
            params.require(&["Seconds"])?;
            Ok(Request::Tick {
                seconds: params.required_integer("Seconds", TICK_SECONDS)?,
            })
        }
        other => Err(invalid_request(format!("unknown command `{other}`"))),
    }
}

fn invalid_request(message: impl Into<String>) -> Error {
    Error::new(ErrorCode::InvalidRequest, message)
}

fn missing(name: &str) -> Error {
    Error::new(ErrorCode::MissingParameter, format!("`{name}` is required"))
}

fn invalid_value(name: &str, expected: &str) -> Error {
    Error::new(
        ErrorCode::InvalidParameterValue,
        format!("`{name}` must be {expected}"),
    )
}

/// Reads a JSON value as an integer within `range`. Numbers written with a fraction or an
/// exponent are not integers.
fn integer_value(name: &str, value: &Value, range: &RangeInclusive<u32>) -> Result<u32> {
    value
        .as_i64()
        .and_then(|n| u32::try_from(n).ok())
        .filter(|n| range.contains(n))
        .ok_or_else(|| {
            invalid_value(
                name,
                &format!("an integer from {} to {}", range.start(), range.end()),
            )
        })
}

/// The members of a command object. A member whose value is `null` counts as absent.
struct Params<'a>(&'a Map<String, Value>);

impl<'a> Params<'a> {
    fn get(&self, name: &str) -> Option<&'a Value> {
        self.0.get(name).filter(|value| !value.is_null())
    }

    /// Fails with `MissingParameter` for the first of `names` that is absent.
    fn require(&self, names: &[&str]) -> Result<()> {
        match names.iter().find(|name| self.get(name).is_none()) {
            Some(name) => Err(missing(name)),
            None => Ok(()),
        }
    }

    fn required_integer(&self, name: &str, range: RangeInclusive<u32>) -> Result<u32> {
        let value = self.get(name).ok_or_else(|| missing(name))?;
        integer_value(name, value, &range)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn code(line: &str) -> ErrorCode {
        parse(line.as_bytes()).unwrap_err().code()
    }

    #[test]
    fn rejects_malformed_shapes() {
        for line in [
            "",
            "   ",
            "[]",
            "\"Tick\"",
            "{",
            "{} trailing",
            "{}",
            r#"{"Command": 1}"#,
            r#"{"Command": null}"#,
            r#"{"Command": "Nope"}"#,
            r#"{"command": "Tick", "Seconds": 1}"#,
        ] {
            assert_eq!(code(line), ErrorCode::InvalidRequest, "{line:?}");
        }
        assert_eq!(
            parse(b"{\"Command\": \"Tick\xff\"}").unwrap_err().code(),
            ErrorCode::InvalidRequest
        );
    }

    #[test]
    fn tick_validates_seconds() {
        assert_eq!(
            parse(br#"{"Command":"Tick","Seconds":5,"Extra":true}"#),
            Ok(Request::Tick { seconds: 5 })
        );
        assert_eq!(code(r#"{"Command":"Tick"}"#), ErrorCode::MissingParameter);
        assert_eq!(
            code(r#"{"Command":"Tick","Seconds":null}"#),
            ErrorCode::MissingParameter
        );
        for bad in ["-1", "1209601", "1.0", "1e1", "\"1\"", "true", "[]"] {
            let line = format!(r#"{{"Command":"Tick","Seconds":{bad}}}"#);
            assert_eq!(code(&line), ErrorCode::InvalidParameterValue, "{bad}");
        }
    }
}
EOF
