//! The broker: the virtual clock and, in later layers, every queue.

use crate::error::Result;
use crate::request::Request;
use crate::response::Reply;
use crate::types::Time;

#[derive(Debug, Default)]
pub struct Broker {
    now: Time,
}

impl Broker {
    pub fn new() -> Self {
        Self::default()
    }

    /// A failed request leaves the broker unchanged.
    pub fn execute(&mut self, request: Request) -> Result<Reply> {
        match request {
            Request::Tick { by } => {
                self.now = self.now.after(by);
                Ok(Reply::Now { now: self.now })
