//! The broker: all queues plus the virtual clock and identifier counters.

use serde_json::{Map, Value};

use crate::error::Result;
use crate::request::Request;

/// The fields a successful command adds to `{"ok": true}`.
pub type Fields = Map<String, Value>;

/// All state of one miniq process.
#[derive(Debug, Default)]
pub struct Broker {
    now: u64,
}

impl Broker {
    /// A broker with no queues and the clock at 0.
    pub fn new() -> Self {
        Self::default()
    }

    /// Executes one request. A failed request changes no state.
    pub fn execute(&mut self, request: Request) -> Result<Fields> {
        match request {
            Request::Tick { seconds } => {
                self.now += u64::from(seconds);
                let mut fields = Fields::new();
                fields.insert("Now".to_owned(), self.now.into());
                Ok(fields)
            }
        }
    }
}
EOF
